    .order-thumb{width:72px;height:72px;border-radius:8px;object-fit:cover;background:#f4f1ea;border:1px solid #dfe8e4;padding:4px}.rules-page{max-width:1120px;margin:auto;padding:28px 18px 40px;position:relative}.rules-page:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 74% 16%,rgba(36,116,95,.08),transparent 23%),radial-gradient(circle at 12% 70%,rgba(244,202,100,.12),transparent 22%);pointer-events:none}.rules-head{position:relative;margin-bottom:24px}.rules-head h2{margin:0;color:#172b27;font-size:32px}.rules-head p{margin:12px 0 0;color:#5e6d70;font-size:18px}.rules-board{position:relative;padding:20px;border:1px solid #dce7e1;border-radius:8px;background:rgba(255,255,255,.86);box-shadow:0 16px 36px rgba(36,48,51,.08);backdrop-filter:blur(8px)}.rules-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.rules-card{overflow:hidden;border:1px solid #dce4e1;border-radius:8px;background:#fff;box-shadow:0 10px 22px rgba(36,48,51,.08)}.rules-card h3{margin:0;padding:18px 18px 14px;font-size:24px;color:#111}.rule-list{display:grid}.rule-item{display:grid;grid-template-columns:70px 1fr;gap:12px;padding:15px 18px;border-top:1px solid #e8efec}.rule-icon{width:58px;height:58px;display:grid;place-items:center;border-radius:8px;background:#eef7f3;font-size:34px}.rule-item strong{display:block;margin-bottom:4px;color:#176b56;font-size:19px}.rule-item p{margin:0;line-height:1.55;color:#21302d}.rules-updated{margin:16px 0 0;color:#667578}.rules-edit{position:relative;margin-top:18px}.rules-admin-note{margin-top:12px;padding:12px;border-radius:8px;background:#eef7f3;color:#1b5e4d}.custom-rule-row{display:grid;grid-template-columns:90px 1fr 2fr auto;gap:10px;align-items:start;padding:12px;border:1px solid #dce7e1;border-radius:8px;background:#fff}.custom-rule-row textarea{min-height:46px}.custom-rule-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:980px){.order-thumb{width:56px;height:56px}.rules-grid{grid-template-columns:1fr}.rules-page{padding:18px 12px}.rules-card h3{font-size:22px}.custom-rule-row{grid-template-columns:1fr}}@media(max-width:620px){.rule-item{grid-template-columns:52px 1fr;padding:14px}.rule-icon{width:48px;height:48px;font-size:28px}.rules-head h2{font-size:28px}}
    .rules-page.list-style{max-width:none;min-height:calc(100vh - 78px);overflow:hidden;margin:-22px calc(50% - 50vw);padding:52px max(28px,calc((100vw - 1120px)/2 + 28px)) 86px;position:relative;background:#f4faf7 url('assets/rules-bg.svg') center/cover no-repeat}.rules-page.list-style:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(244,250,247,.88),rgba(244,250,247,.72) 52%,rgba(244,250,247,.58));pointer-events:none}.rules-page.list-style:after{display:none}.rules-head{position:relative;z-index:1;max-width:900px;margin:0 auto 24px}.rules-head h2{font-size:34px}.rules-list-board,.rules-edit{position:relative;z-index:1;max-width:900px;margin-left:auto;margin-right:auto}.rules-list-board{display:grid;gap:12px;padding:26px 28px;border:1px solid rgba(204,220,214,.9);border-radius:8px;background:rgba(255,255,255,.88);box-shadow:0 20px 44px rgba(36,48,51,.1);backdrop-filter:blur(8px)}.rules-list-item{display:grid;grid-template-columns:64px 1fr;gap:14px;align-items:start;padding:16px;border:1px solid #e0e9e5;border-radius:8px;background:#fff;box-shadow:0 8px 18px rgba(36,48,51,.06)}.rules-list-item .rule-icon{width:56px;height:56px}.rules-list-item strong{font-size:19px;color:#176b56}.rules-list-item p{margin:5px 0 0;line-height:1.65}.rules-list-item small{display:block;margin-top:6px;color:#7a898b}.rules-illustrations{display:none}.rules-text-editor{min-height:300px;line-height:1.9;background:rgba(255,255,255,.94);border-color:#bdd4cd;box-shadow:inset 0 1px 6px rgba(36,48,51,.06);font-size:17px}.rules-edit{margin-top:18px;background:rgba(255,255,255,.88);backdrop-filter:blur(8px)}.rules-edit .custom-rule-row{grid-template-columns:82px minmax(130px,.8fr) minmax(170px,1fr) minmax(260px,2fr) auto}.rules-edit .custom-rule-row label{display:grid;gap:6px;font-weight:700;color:#35504a}.rules-edit .custom-rule-row input,.rules-edit .custom-rule-row textarea{font-weight:400}.rules-edit .custom-rule-row button{align-self:end}@media(max-width:980px){.rules-page.list-style{margin:-22px -12px;padding:34px 16px 58px}.rules-edit .custom-rule-row{grid-template-columns:1fr}.rules-edit .custom-rule-row button{justify-self:start}}@media(max-width:620px){.rules-list-board{padding:18px}.rules-list-item{grid-template-columns:50px 1fr;padding:14px}.rules-list-item .rule-icon{width:46px;height:46px;font-size:26px}.rules-text-editor{font-size:16px}}
    .notice-wrap{position:relative}.notice-btn{position:relative}.notice-badge{position:absolute;right:-5px;top:-7px;min-width:19px;height:19px;padding:0 5px;border-radius:999px;background:#e53935;color:#fff;font-size:12px;font-weight:900;line-height:19px;text-align:center;box-shadow:0 0 0 2px #0f5445}.notice-badge.hidden{display:none}.notice-menu{position:absolute;right:0;top:52px;width:min(360px,calc(100vw - 24px));max-height:440px;overflow:auto;padding:12px;border:1px solid #dce7e1;border-radius:8px;background:#fff;color:var(--ink);box-shadow:0 18px 42px rgba(20,54,45,.22);z-index:30}.notice-menu h3{margin:0 0 10px;color:#123b32}.notice-item{width:100%;text-align:left;display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;padding:12px;border:1px solid #e0e9e5;border-radius:8px;background:#fff!important;color:var(--ink)!important}.notice-item+.notice-item{margin-top:8px}.notice-item strong{color:#123b32}.notice-dot{width:8px;height:8px;border-radius:50%;background:#e53935}.notice-empty{margin:0;padding:18px;text-align:center;color:var(--muted);background:#f6fbf8;border-radius:8px}@media(max-width:620px){.notice-menu{position:fixed;right:12px;left:12px;top:112px;width:auto}.notice-badge{box-shadow:0 0 0 2px #176b56}}
    .notice-preview{display:block;margin-top:4px;color:#5d6d70;font-size:13px;line-height:1.45}.notice-action{display:inline-flex;margin-top:8px;padding:4px 8px;border-radius:999px;background:#eef7f3;color:#176b56;font-size:12px;font-weight:800}.notice-time{display:block;margin-top:4px;color:#8a9698;font-size:12px}
  </style>
</head>
<body>
<div id="app"></div><div id="modal" class="modal hidden"></div>
<script>
let me=null,opts={schools:[],categories:[]},view='market',activeThread=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const fallbackImage='data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22900%22%20height%3D%22675%22%20viewBox%3D%220%200%20900%20675%22%3E%3Crect%20width%3D%22900%22%20height%3D%22675%22%20fill%3D%22%23eef5f2%22%2F%3E%3Crect%20x%3D%22190%22%20y%3D%22150%22%20width%3D%22520%22%20height%3D%22330%22%20rx%3D%2228%22%20fill%3D%22%23fff%22%20stroke%3D%22%23c8d8d3%22%20stroke-width%3D%228%22%2F%3E%3Cpath%20d%3D%22M260%20420h380l-110-135-80%2092-62-70z%22%20fill%3D%22%239fcfbf%22%2F%3E%3Ccircle%20cx%3D%22610%22%20cy%3D%22235%22%20r%3D%2238%22%20fill%3D%22%23f4ca64%22%2F%3E%3Ctext%20x%3D%22450%22%20y%3D%22555%22%20text-anchor%3D%22middle%22%20font-family%3D%22Arial%2Csans-serif%22%20font-size%3D%2244%22%20font-weight%3D%22700%22%20fill%3D%22%2324745f%22%3E%E6%A0%A1%E5%9C%92%E4%BA%8C%E6%89%8B%E4%BA%A4%E6%98%93%E5%B9%B3%E5%8F%B0%3C%2Ftext%3E%3C%2Fsvg%3E';
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const money=n=>'NT$ '+Number(n||0).toLocaleString('zh-TW');
const statusLabel=s=>({listed:'已上架',pausing:'下架中',removed:'已下架',reported_removed:'被檢舉下架',sold:'已售出',in_progress:'進行中',completed:'已完成',cancelled:'已取消',pending:'待處理',approved:'通過',rejected:'退回'}[s]||s);
async function api(action,data=null,method='POST'){const r=await fetch('api.php?action='+action,{method:data?method:'GET',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):null});const j=await r.json();if(!j.ok)throw new Error(j.message||'操作失敗');return j}
async function init(){try{const m=await api('me');me=m.user;const o=await api('options');opts=o;render()}catch(e){renderLogin()}}
function renderLogin(){app.innerHTML=`<div class="login"><span class="doodle one"></span><span class="doodle two"></span><span class="doodle three"></span><span class="doodle four"></span><span class="doodle five"></span><span class="doodle six"></span><div class="login-stage"><section class="login-poster"><div class="poster-board"><img src="assets/login-hero.png" alt="校園二手交易平台插圖"></div><div class="login-title"><h1>校園二手交易平台</h1><p>讓好物延續故事，打造校園專屬的安心交易空間</p></div></section><form class="login-card" onsubmit="login(event)"><div><h2>歡迎回來</h2><p class="muted">登入後即可搜尋商品、管理上架、查看訂單與訊息。</p></div><label>帳號<input name="username" autocomplete="username" placeholder="帳號" required></label><label>密碼<input name="password" type="password" autocomplete="current-password" placeholder="密碼" required></label><button>登入</button><button type="button" class="secondary" onclick="openRegister()">註冊學生帳號</button><div class="demo-box"><h3>示範帳號</h3><div class="demo-grid"><button type="button" class="demo-card" onclick="fillLoginDemo('buyer')"><span class="demo-icon">B</span>Buyer</button><button type="button" class="demo-card" onclick="fillLoginDemo('seller')"><span class="demo-icon">S</span>Seller</button><button type="button" class="demo-card" onclick="fillLoginDemo('admin')"><span class="demo-icon">A</span>Admin</button></div></div><p class="muted login-footnote">平台方帳號由資料庫預先建立，一般使用者只能註冊學生帳號。</p></form></div></div>`}
function fillLoginDemo(role){const accounts={buyer:['buyer','buyer123'],seller:['seller','seller123'],admin:['admin','admin123']},form=document.querySelector('.login-card');if(!form||!accounts[role])return;form.username.value=accounts[role][0];form.password.value=accounts[role][1];form.password.focus()}
async function login(e){e.preventDefault();try{const res=await api('login',Object.fromEntries(new FormData(e.target)));me=res.user;if(res.warning)alert(res.warning);await loadOptions();render()}catch(err){alert(err.message)}}
async function logout(){await api('logout',{});me=null;renderLogin()}
async function loadOptions(){opts=await api('options')}
function openRegister(){modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><h2>註冊</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="register(event)"><div class="two grid"><label>帳號<input name="username" required></label><label>密碼<input name="password" type="password" required></label></div><div class="two grid"><label>Email<input name="email" type="email" required></label><label>姓名<input name="name" required></label></div><label>學校<select name="school">${opts.schools.map(s=>`<option>${esc(s.name)}</option>`)}</select></label><label>自我介紹<textarea name="bio"></textarea></label><button>建立帳號</button></form></div>`}
async function register(e){e.preventDefault();try{me=(await api('register',Object.fromEntries(new FormData(e.target)))).user;closeModal();render()}catch(err){alert(err.message)}}
function shell(content){app.innerHTML=`<header class="top"><div><div class="brand">校園二手交易平台</div><div class="muted">${esc(me.display_name)}｜${me.role==='admin'?'平台方':'學生帳號'}</div></div><nav class="nav">${me.role==='admin'?`<button class="active">平台管理</button>`:['market:買家功能','sell:賣家功能','messages:訊息','orders:訂單'].map(x=>{let [id,t]=x.split(':');return `<button class="${view===id?'active':''}" onclick="view='${id}';render()">${t}</button>`}).join('')}</nav><button class="secondary" onclick="logout()">登出</button></header><main>${content}</main>`}
async function render(){if(!me)return renderLogin();await loadOptions();if(me.role==='admin')return renderAdmin();if(view==='sell')return renderSell();if(view==='messages')return renderMessages();if(view==='orders')return renderOrders();return renderMarket()}
async function renderMarket(){shell(`<div class="head"><div><h2>買家功能｜尋找商品</h2><p class="muted">搜尋商品、私訊賣家、提出面交訂單，也可以推薦新增分類或大學。</p></div><div><button class="secondary" onclick="requestForm('category')">推薦分類</button> <button class="secondary" onclick="requestForm('school')">推薦大學</button></div></div><div class="toolbar"><input id="q" placeholder="搜尋"><select id="school"><option value="">全部學校</option>${opts.schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`)}</select><select id="cat"><option value="">全部分類</option>${opts.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`)}</select><select id="sort"><option value="new">最新</option><option value="cheap">最便宜</option></select></div><button onclick="loadProducts()">查看分類/搜尋</button><div id="products" class="products"></div>`);loadProducts()}
async function loadProducts(){const q=document.querySelector('#q')?.value||'',s=document.querySelector('#school')?.value||'',c=document.querySelector('#cat')?.value||'',sort=document.querySelector('#sort')?.value||'new';const data=await api(`products&q=${encodeURIComponent(q)}&school_id=${s}&category_id=${c}&sort=${sort}`);document.querySelector('#products').innerHTML=data.products.map(p=>`<article class="card"><img src="${esc(p.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt=""><div class="body"><h3>${esc(p.title)}</h3><div class="price">${money(p.price)}</div><div><span class="pill">${esc(p.school_name)}</span> <span class="pill">${esc(p.category_name)}</span></div><p class="muted">賣家 ${esc(p.seller_name)}</p><button onclick="openProduct(${p.id})">查看</button></div></article>`).join('')||'<p class="muted">沒有商品。</p>'}
async function openProduct(id,readOnly=false){const d=await api('product_detail&id='+id);const p=d.product;modal.classList.remove('hidden');const actions=!readOnly&&p.seller_id!=me.id&&p.status==='listed'?`<p><button onclick="sendMessageForm(${p.id},${p.seller_id})">私訊賣家</button> <button onclick="createOrder(${p.id})">提出面交訂單</button> ${Number(p.report_cleared||0)===1?"":`<button class="danger" onclick="reportForm(${p.id})">檢舉商品</button>`}</p>`:'';const commentArea=readOnly?'<hr><h3>公開留言</h3>':`<hr><form class="grid" onsubmit="comment(event,${p.id})"><label>公開留言<textarea name="text" required></textarea></label><button>留言</button></form>`;modal.innerHTML=`<div><div class="head"><h2>${esc(p.title)}</h2><button class="secondary" onclick="closeModal()">關閉</button></div><img class="card" style="width:100%;max-height:320px" src="${esc(p.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt=""><p class="price">${money(p.price)}</p><p>${esc(p.description)}</p><p class="muted">${esc(p.school_name)}｜${esc(p.category_name)}</p>${Number(p.report_cleared||0)===1?`<p class="pill" style="background:#eef8f1;color:#23624d">平台已審核：符合規定，無法再次檢舉</p>`:""}${p.status!=='listed'?`<p class="pill">目前狀態：${statusLabel(p.status)}</p>`:''}${userChip(p.seller_id,p.seller_name,p.seller_avatar_url,'seller',p.seller_rating,p.seller_rating_count,p.seller_school_name)}${actions}${readOnly?'<p class="muted">平台方檢視模式：此頁僅供查看商品內容，不能進行交易、修改、留言或檢舉。</p>':''}${commentArea}<div class="list">${d.comments.map(c=>`<div class="row"><div><strong>${esc(c.user_name)}</strong><br>${esc(c.comment_text)}</div></div>`).join('')}</div></div>`}
async function comment(e,id){e.preventDefault();await api('comment',{product_id:id,text:new FormData(e.target).get('text')});openProduct(id)}
function requestForm(type){modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><h2>${type==='school'?'推薦新增大學':'推薦新增分類'}</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="submitRequest(event,'${type}')"><label>名稱<input name="name" required></label><button>送出審核</button></form></div>`}
async function submitRequest(e,type){e.preventDefault();await api(type==='school'?'request_school':'request_category',{name:new FormData(e.target).get('name')});closeModal();alert('已送出申請')}
function reportForm(id){modal.innerHTML=`<div><div class="head"><h2>檢舉商品</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="submitReport(event,${id})"><label>原因<textarea name="reason" required></textarea></label><button class="danger">送出檢舉</button></form></div>`}
async function submitReport(e,id){e.preventDefault();try{await api('report',{product_id:id,reason:new FormData(e.target).get('reason')});closeModal();alert('檢舉已送出')}catch(err){alert(err.message||'檢舉送出失敗')}}
async function createOrder(id){await api('create_order',{product_id:id});closeModal();view='orders';render()}
function closeModal(){modal.classList.add('hidden');modal.innerHTML=''}
function imgToData(file){return new Promise(resolve=>{if(!file||!file.name)return resolve('');const img=new Image(),fr=new FileReader();fr.onload=()=>{img.onload=()=>{const canvas=document.createElement('canvas');let w=img.width,h=img.height,max=760;if(w>h&&w>max){h=Math.round(h*max/w);w=max}else if(h>max){w=Math.round(w*max/h);h=max}canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,0,0,w,h);let q=.78,data=canvas.toDataURL('image/jpeg',q);while(data.length>60000&&q>.35){q-=.08;data=canvas.toDataURL('image/jpeg',q)}resolve(data.length>60000?'':data)};img.onerror=()=>resolve('');img.src=fr.result};fr.onerror=()=>resolve('');fr.readAsDataURL(file)})}
async function renderSell(){shell(`<div class="split"><form class="panel grid" onsubmit="createProduct(event)"><h2>賣家功能｜上架商品</h2><label>商品名稱<input name="title" required></label><label>價格<input name="price" type="number" required></label><label>學校<select name="school_id">${opts.schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`)}</select></label><label>分類<select name="category_id">${opts.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`)}</select></label><label>新舊程度<select name="condition_label"><option value="new">全新</option><option value="like_new">九成新</option><option value="good">八成新</option><option value="fair">七成新</option><option value="worn">有使用痕跡</option></select></label><label>圖片<input name="image" type="file" accept="image/*"></label><label>描述<textarea name="description" required></textarea></label><button>上架</button></form><div class="panel"><h2>我的商品</h2><div class="nav"><button class="active" onclick="loadSellerProducts('listed',this)">已上架</button><button onclick="loadSellerProducts('removed',this)">已下架</button><button onclick="loadSellerProducts('sold',this)">已售出</button></div><div id="sellerProducts" class="list" style="margin-top:12px"></div></div></div>`);loadSellerProducts('listed')}
async function createProduct(e){e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('button');try{if(btn){btn.disabled=true;btn.textContent='上架中'}await api('create_product',{title:f.get('title'),price:f.get('price'),school_id:f.get('school_id'),category_id:f.get('category_id'),condition_label:f.get('condition_label'),description:f.get('description'),image_url:await imgToData(f.get('image'))});alert('已上架');renderSell()}catch(err){alert(err.message||'上架失敗')}finally{if(btn){btn.disabled=false;btn.textContent='上架'}}}
async function loadSellerProducts(status,btn=null){if(btn){document.querySelectorAll('.panel .nav button').forEach(b=>b.classList.remove('active'));btn.classList.add('active')}const d=await api('seller_products');window.sellerProductCache=d.products;const rows=d.products.filter(p=>status==='reported_removed'?Number(p.locked_by_report||0)===1:status==='removed'?['removed','pausing'].includes(p.status)&&Number(p.locked_by_report||0)!==1:p.status===status&&Number(p.locked_by_report||0)!==1);document.querySelector('#sellerProducts').innerHTML=rows.map(p=>{const locked=Number(p.locked_by_report||0)===1;return `<div class="row"><div><strong>${esc(p.title)}</strong><br><span class="muted">${locked?'被檢舉下架':statusLabel(p.status)}｜${money(p.price)}｜${esc(p.school_name)}｜${esc(p.category_name)}｜訂單 ${p.order_count}</span>${locked?`<p class="muted" style="margin:8px 0 0;color:#8a3434">下架原因：${esc(p.removed_reason||'檢舉成立，違反網站規範')}</p><p class="muted" style="margin:4px 0 0">此商品已被鎖定，不能再次上架。</p>`:''}</div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><button class="secondary" onclick="openProduct(${p.id})">查看</button>${locked?'':`<button class="secondary" onclick="editProductForm(${p.id})">修改商品</button><select onchange="updateProductStatus(${p.id},this.value)"><option value="listed" ${p.status==='listed'?'selected':''}>已上架</option><option value="removed" ${p.status==='removed'||p.status==='pausing'?'selected':''}>已下架</option><option value="sold" ${p.status==='sold'?'selected':''}>已售出</option></select>`}${locked?'<span class="pill" style="background:#fdecec;color:#8a3434">不可再次上架</span>':''}</div></div>`}).join('')||'<p class="muted">目前沒有此狀態的商品。</p>'}
function editProductForm(id){const p=(window.sellerProductCache||[]).find(x=>String(x.id)===String(id));if(!p)return alert('找不到商品資料');modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><h2>修改商品</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="updateProduct(event,${id})"><label>商品名稱<input name="title" value="${esc(p.title)}" required></label><label>價格<input name="price" type="number" value="${esc(p.price)}" required></label><label>學校<select name="school_id">${opts.schools.map(s=>`<option value="${s.id}" ${String(p.school_id)===String(s.id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>分類<select name="category_id">${opts.categories.map(c=>`<option value="${c.id}" ${String(p.category_id)===String(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>新舊程度<select name="condition_label"><option value="new" ${p.condition_label==='new'?'selected':''}>全新</option><option value="like_new" ${p.condition_label==='like_new'?'selected':''}>九成新</option><option value="good" ${p.condition_label==='good'?'selected':''}>八成新</option><option value="fair" ${p.condition_label==='fair'?'selected':''}>七成新</option><option value="worn" ${p.condition_label==='worn'?'selected':''}>有使用痕跡</option></select></label><label>更換圖片（可不選）<input name="image" type="file" accept="image/*"></label><label>描述<textarea name="description" required>${esc(p.description||'')}</textarea></label><button>儲存修改</button></form></div>`}
async function updateProduct(e,id){e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('button:last-child');try{if(btn){btn.disabled=true;btn.textContent='儲存中'}await api('update_product',{product_id:id,title:f.get('title'),price:f.get('price'),school_id:f.get('school_id'),category_id:f.get('category_id'),condition_label:f.get('condition_label'),description:f.get('description'),image_url:await imgToData(f.get('image'))});closeModal();alert('商品已更新');renderSell()}catch(err){alert(err.message||'修改失敗')}finally{if(btn){btn.disabled=false;btn.textContent='儲存修改'}}}
async function updateProductStatus(id,status){await api('update_product_status',{product_id:id,status});loadSellerProducts(status)}
function sendMessageForm(pid,receiver){modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><h2>私訊</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="sendMessage(event,${pid},${receiver})"><label>訊息<textarea name="text" required></textarea></label><button>送出</button></form></div>`}
async function sendMessage(e,pid,receiver){e.preventDefault();await api('send_message',{product_id:pid,receiver_id:receiver,text:new FormData(e.target).get('text')});closeModal();view='messages';render()}
async function renderMessages(){const d=await api('messages');shell(`<div class="chat"><div class="list">${d.threads.map(t=>`<button class="secondary" onclick="activeThread=${t.id};renderMessages()">${esc(t.product_title)}<br>${esc(t.buyer_name)} / ${esc(t.seller_name)}</button>`).join('')||'尚無訊息'}</div><div class="panel">${activeThread?chatPane(d):'請選擇對話'}</div></div>`)}
function chatPane(d){const ms=d.messages[activeThread]||[],t=d.threads.find(x=>x.id==activeThread);return `<h2>${esc(t.product_title)}</h2><div class="grid">${ms.map(m=>`<div class="bubble ${m.sender_id==me.id?'mine':''}"><strong>${esc(m.sender_name)}</strong><br>${esc(m.message_text)}</div>`).join('')}</div><form class="grid" onsubmit="replyMessage(event,${activeThread})"><textarea name="text" required></textarea><button>回覆</button></form>`}
async function replyMessage(e,thread){e.preventDefault();await api('send_message',{thread_id:thread,text:new FormData(e.target).get('text')});renderMessages()}
async function renderOrders(){const d=await api('orders');shell(`<h2>訂單</h2><div class="list">${d.orders.map(o=>`<div class="row"><div><strong>${esc(o.product_title)}</strong><br>${o.status}｜${money(o.price)}｜買家 ${esc(o.buyer_name)}｜賣家 ${esc(o.seller_name)}</div><div>${o.status==='in_progress'?`<button onclick="completeOrder(${o.id})">完成訂單</button>`:''} ${o.status==='completed'?`<button class="secondary" onclick="rateForm(${o.id})">評價</button>`:''}</div></div>`).join('')||'尚無訂單'}</div>`)}
async function completeOrder(id){try{await api('complete_order',{order_id:id});alert('訂單已完成，通知信已寄出');renderOrders()}catch(e){alert(e.message)}}
function rateForm(id){const o=(window.orderCache||[]).find(x=>String(x.id)===String(id)),isBuyer=o&&Number(o.buyer_id)===Number(me.id),target=isBuyer?'賣家':'買家',samples=isBuyer?['物品完整符合預期','賣家態度良好','交易迅速有效率','回覆迅速','物品乾淨','面交準時']:['買家態度良好','溝通清楚有禮貌','交易很快很愉快','面交準時','付款乾脆有效率','確認商品很配合'];modal.classList.remove('hidden');modal.innerHTML=`<div class="rating-modal"><div class="head"><div><h2>評價${target}</h2><p class="muted">${o?`商品：${esc(o.product_title)}`:'分享這次交易經驗'}</p></div><button type="button" class="secondary" onclick="closeModal()">關閉</button></div><form class="grid rating-form" onsubmit="rate(event,${id})"><div class="rating-control"><div class="rating-top"><strong>整體評分</strong><span class="rating-score"><span id="ratingValue">5</span> / 5 優良</span></div><div class="rating-slider" style="--rating-fill:100%"><input name="score" type="range" min="1" max="5" step="1" value="5" oninput="updateRatingText(this.value)"><span class="rating-star">★</span></div><div class="rating-scale"><span>1 差</span><span>5 優良</span></div></div><label class="comment-field"><span class="comment-hint">分享您的經驗並幫助大家作出更好的選擇</span><textarea name="text"></textarea></label><div class="sample-comments">${samples.map(s=>`<button type="button" onclick="setReviewComment('${esc(s)}')">${esc(s)}</button>`).join('')}</div><button type="submit" class="rating-submit">送出</button></form></div>`}
function updateRatingText(value){const n=Number(value),labels={1:'差',2:'待改進',3:'普通',4:'良好',5:'優良'},slider=document.querySelector('.rating-slider'),box=document.querySelector('.rating-score');if(slider)slider.style.setProperty('--rating-fill',`${(n-1)/4*100}%`);if(box)box.innerHTML=`<span id="ratingValue">${n}</span> / 5 ${labels[n]||''}`}
function setReviewComment(text){const textarea=document.querySelector('.rating-form textarea[name="text"]');if(textarea){textarea.value=text;textarea.focus()}}
async function rate(e,id){e.preventDefault();const f=new FormData(e.target),btn=e.target.querySelector('.rating-submit');try{if(btn){btn.disabled=true;btn.textContent='送出中'}await api('rate',{order_id:id,score:f.get('score'),text:f.get('text')});closeModal();alert('已評價');renderOrders()}catch(err){alert(err.message||'評價送出失敗');if(btn){btn.disabled=false;btn.textContent='送出'}}}
async function renderAdmin(){const d=await api('admin_dashboard');const total=d.sales_summary||{},month=d.month_summary||{},reports=d.reports||[];const pendingMap={};reports.filter(r=>r.status==='pending').forEach(r=>{const key=String(r.product_id);if(!pendingMap[key])pendingMap[key]={...r,reasons:[],report_count:0};pendingMap[key].report_count++;pendingMap[key].reasons.push(r)});const pending=Object.values(pendingMap),done=reports.filter(r=>r.status!=='pending');shell(`<div class="head"><div><h2>平台管理</h2><p class="muted">同一商品的多筆檢舉會合併成一列審核。</p></div><button class="secondary" onclick="resetModerationLocks()">解除所有停權與檢舉鎖定</button></div><div class="statgrid"><div class="stat"><span>總售出件數</span><strong>${total.sold_count||0}</strong></div><div class="stat"><span>總成交額</span><strong>${money(total.revenue||0)}</strong></div><div class="stat"><span>本月售出</span><strong>${month.sold_count||0}</strong></div><div class="stat"><span>本月成交額</span><strong>${money(month.revenue||0)}</strong></div></div><div class="split"><div class="panel"><h3>近 6 個月成交額</h3>${barRows(d.monthly_sales||[])}</div><div class="panel"><h3>待審檢舉</h3><div class="list">${pending.map(r=>`<div class="row"><div><strong>${esc(r.product_title)}</strong><br><span class="pill">${r.report_count} 筆檢舉</span><div class="list" style="margin-top:8px">${r.reasons.map(x=>`<div class="muted">檢舉內容：${esc(x.reason)}</div>`).join('')}</div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="secondary" onclick="openProduct(${r.product_id},true)">查看商品</button><button onclick="reviewReport(${r.id},true,${r.product_id})">下架</button><button class="secondary" onclick="reviewReport(${r.id},false,${r.product_id})">保留</button></div></div>`).join('')||'<p class="muted">尚無待審檢舉</p>'}</div>${done.length?`<details style="margin-top:14px"><summary class="muted">已完成審核 ${done.length} 筆</summary><div class="list" style="margin-top:12px">${done.map(r=>`<div class="row"><div><strong>${esc(r.product_title)}</strong><br><span class="muted">檢舉原因：${esc(r.reason)}</span><br><span class="muted">狀態：${statusLabel(r.status)}</span>${r.admin_comment?`<p class="muted" style="margin:6px 0 0">平台評語：${esc(r.admin_comment)}</p>`:''}</div><button class="secondary" onclick="openProduct(${r.product_id},true)">查看商品</button></div>`).join('')}</div></details>`:''}</div></div><div class="split" style="margin-top:16px"><div class="panel"><h3>分類申請</h3>${d.category_requests.map(r=>reqRow(r,'category')).join('')||'<p class="muted">尚無申請</p>'}</div><div class="panel"><h3>大學申請</h3>${d.school_requests.map(r=>reqRow(r,'school')).join('')||'<p class="muted">尚無申請</p>'}</div></div><div class="panel" style="margin-top:16px"><h3>售出商品統整</h3>${soldTable(d.sold_items||[],true)}</div><div class="panel" style="margin-top:16px"><h3>所有訂單</h3>${d.orders.map(o=>`<p>${esc(o.product_title)}｜${statusLabel(o.status)}</p>`).join('')||'<p class="muted">尚無訂單</p>'}</div>`)}
async function resetModerationLocks(){if(!confirm('確定要解除目前所有帳號停權與商品檢舉鎖定嗎？'))return;try{await api('reset_moderation_locks',{});alert('已解除所有停權與檢舉鎖定');renderAdmin()}catch(err){alert(err.message)}}
function reqRow(r,type){return `<div class="row"><div>${esc(r.requested_name)}｜${esc(r.requester_name)}｜${r.status}</div><div>${r.status==='pending'?`<button onclick="reviewReq('${type}',${r.id},true)">通過</button><button class="secondary" onclick="reviewReq('${type}',${r.id},false)">退回</button>`:''}</div></div>`}
async function reviewReq(type,id,approved){await api('review_request',{type,id,approved});renderAdmin()}
function reviewReport(id,approved,productId=null){modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><h2>${approved?'審核通過｜下架商品':'審核退回｜保留商品'}</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="submitReviewReport(event,${id},${approved},${productId??'null'})"><label>平台方審核評語<textarea name="comment" required placeholder="請輸入給賣方與檢舉申請人的審核說明"></textarea></label><button>${approved?'確認下架':'確認保留'}</button></form></div>`}
async function submitReviewReport(e,id,approved,productId=null){e.preventDefault();const comment=new FormData(e.target).get('comment');try{await api('review_report',{id,approved,product_id:productId,comment});closeModal();renderAdmin()}catch(err){alert(err.message)}}

function initials(name){return String(name||'?').trim().slice(0,1).toUpperCase()}
function shell(content){app.innerHTML=`<header class="top"><div><div class="brand">校園二手交易平台</div><div class="muted">${esc(me.display_name)}｜${me.role==='admin'?'平台方':'學生帳號'}</div></div><nav class="nav">${me.role==='admin'?`<button class="${view==='admin'?'active':''}" onclick="view='admin';render()">平台管理</button>`:['market:買家功能','sell:賣家功能','messages:訊息','orders:訂單'].map(x=>{let [id,t]=x.split(':');return `<button class="${view===id?'active':''}" onclick="view='${id}';render()">${t}</button>`}).join('')}</nav><div class="top-actions"><button class="avatar" title="個人中心" onclick="view='profile';render()">${esc(initials(me.display_name))}</button><button class="secondary" onclick="logout()">登出</button></div></header><main>${content}</main>`}
async function render(){if(!me)return renderLogin();await loadOptions();if(view==='rules')return renderRules();if(view==='profile')return renderProfile();if(me.role==='admin')return renderAdmin();if(view==='sell')return renderSell();if(view==='messages')return renderMessages();if(view==='orders')return renderOrders();return renderMarket()}
async function renderProfile(){const d=await api('profile');const p=d.profile;const orders=d.buyer_orders||[],reports=d.reports||[];shell(`<div class="head"><div><h2>個人中心</h2><p class="muted">修改註冊資料、頭像，並查看買家購買紀錄與檢舉結果。</p></div></div><div class="split"><form class="panel grid" onsubmit="updateProfile(event)"><h3>更改資料</h3><div class="user-chip">${avatarHtml(p.avatar_url,p.display_name,'avatar')}<span class="muted">目前頭像</span></div><label>更換頭像（可不選）<input name="avatar" type="file" accept="image/*"></label><label>姓名<input name="display_name" value="${esc(p.display_name)}" required></label><label>Email<input name="email" type="email" value="${esc(p.email)}" required></label><label>學校<select name="school_id">${opts.schools.map(s=>`<option value="${s.id}" ${String(p.school_id)===String(s.id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>自我介紹<textarea name="bio">${esc(p.bio||'')}</textarea></label><button>儲存資料</button></form><div class="panel"><h3>帳號資訊</h3><p>帳號：${esc(p.username)}</p><p>Email：${esc(p.email)}</p><p>學校：${esc(p.school_name||'未設定')}</p><p>身份：${p.role==='admin'?'平台方':'學生帳號'}</p><button class="secondary" onclick="openPublicProfile(${p.id},'buyer')">查看我的買家公開頁</button> <button class="secondary" onclick="openPublicProfile(${p.id},'seller')">查看我的賣家公開頁</button></div></div><div class="panel" style="margin-top:16px"><h3>買家購買紀錄</h3><table class="table"><thead><tr><th>建立時間</th><th>商品</th><th>金額</th><th>賣家</th><th>學校</th><th>分類</th><th>狀態</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.created_at||'')}</td><td>${esc(o.product_title)}</td><td>${money(o.price)}</td><td>${esc(o.seller_name)}</td><td>${esc(o.school_name)}</td><td>${esc(o.category_name)}</td><td>${statusLabel(o.status)}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">目前沒有購買紀錄</td></tr>'}</tbody></table></div><div class="panel" style="margin-top:16px"><h3>我的檢舉結果</h3><table class="table"><thead><tr><th>檢舉時間</th><th>商品</th><th>檢舉原因</th><th>狀態</th><th>平台評語</th></tr></thead><tbody>${reports.map(r=>`<tr><td>${esc(r.created_at||'')}</td><td>${esc(r.product_title)}</td><td>${esc(r.reason||'')}</td><td>${statusLabel(r.status)}</td><td>${esc(r.admin_comment||'尚未審核')}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">目前沒有檢舉紀錄</td></tr>'}</tbody></table></div>`)}
async function updateProfile(e){e.preventDefault();const f=new FormData(e.target);try{me=(await api('update_profile',{display_name:f.get('display_name'),email:f.get('email'),school_id:f.get('school_id'),bio:f.get('bio')})).user;alert('資料已更新');renderProfile()}catch(err){alert(err.message)}}
async function renderMessages(){const d=await api('messages');if(!activeThread&&d.threads[0])activeThread=d.threads[0].id;shell(`<div class="head"><div><h2>訊息中心</h2><p class="muted">依商品建立對話，買家和賣家可以在這裡持續溝通面交細節。</p></div></div><div class="chat"><div class="panel"><h3>對話列表</h3><div class="list">${d.threads.map(t=>`<button class="thread-btn ${activeThread==t.id?'active':''}" onclick="activeThread=${t.id};renderMessages()"><strong>${esc(t.product_title)}</strong><br><span class="muted">${esc(t.buyer_name)} / ${esc(t.seller_name)}</span><br><span>${money(t.price)}</span></button>`).join('')||'<p class="muted">尚無私訊，可從商品頁點選私訊賣家開始。</p>'}</div></div><div class="panel chat-panel">${activeThread?chatPane(d):'<p class="muted">請選擇左側對話。</p>'}</div></div>`)}
function chatPane(d){const ms=d.messages[activeThread]||[],t=d.threads.find(x=>x.id==activeThread);return `<div><h3>${esc(t.product_title)}</h3><p class="muted">買家 ${esc(t.buyer_name)}｜賣家 ${esc(t.seller_name)}｜${money(t.price)}</p></div><div class="message-list grid">${ms.map(m=>`<div class="bubble ${m.sender_id==me.id?'mine':''}"><strong>${m.sender_id==me.id?'我':esc(m.sender_name)}</strong><br>${esc(m.message_text)}<small>${esc(m.created_at||'')}</small></div>`).join('')||'<p class="muted">尚無訊息。</p>'}</div><form class="grid" onsubmit="replyMessage(event,${activeThread})"><label>輸入訊息<textarea name="text" required placeholder="輸入面交時間、地點或商品問題"></textarea></label><button>送出訊息</button></form>`}
function countStatus(rows,status){return rows.find(r=>r.status===status)?.count_value||0}
function barRows(rows,labelKey='month_label',valueKey='revenue'){const max=Math.max(1,...rows.map(r=>Number(r[valueKey]||0)));return `<div class="bars">${rows.map(r=>`<div class="bar"><span>${esc(r[labelKey]||'未分類')}</span><div class="track"><div class="fill" style="width:${Number(r[valueKey]||0)/max*100}%"></div></div><span>${valueKey==='revenue'?money(r[valueKey]):r[valueKey]}</span></div>`).join('')||'<p class="muted">尚無資料</p>'}</div>`}
function soldTable(rows,showSeller=false){return `<table class="table"><thead><tr><th>售出時間</th><th>商品</th><th>金額</th><th>買家</th>${showSeller?'<th>賣家</th>':''}<th>分類</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.completed_at||'尚無')}</td><td>${esc(r.product_title||r.title)}</td><td>${money(r.price)}</td><td>${esc(r.buyer_name||'')}</td>${showSeller?`<td>${esc(r.seller_name||'')}</td>`:''}<td>${esc(r.category_name||'')}</td></tr>`).join('')||`<tr><td colspan="${showSeller?6:5}" class="muted">目前尚無售出資料</td></tr>`}</tbody></table>`}
async function renderSell(){shell(`<div class="head"><div><h2>賣家功能｜商品與銷售中心</h2><p class="muted">管理自己的商品狀態，並查看已售出商品與銷售表現。</p></div></div><div id="sellerStats"></div><div class="split"><form class="panel grid" onsubmit="createProduct(event)"><h2>上架商品</h2><label>商品名稱<input name="title" required></label><label>價格<input name="price" type="number" required></label><label>學校<select name="school_id">${opts.schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`)}</select></label><label>分類<select name="category_id">${opts.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`)}</select></label><label>新舊程度<select name="condition_label"><option value="new">全新</option><option value="like_new">九成新</option><option value="good">八成新</option><option value="fair">七成新</option><option value="worn">有使用痕跡</option></select></label><label>圖片<input name="image" type="file" accept="image/*"></label><label>描述<textarea name="description" required></textarea></label><button>上架</button></form><div class="panel"><h2>我的商品</h2><div class="nav"><button class="active" onclick="loadSellerProducts('listed',this)">已上架</button><button onclick="loadSellerProducts('removed',this)">已下架</button><button onclick="loadSellerProducts('reported_removed',this)">被檢舉下架</button><button onclick="loadSellerProducts('sold',this)">已售出</button></div><div id="sellerProducts" class="list" style="margin-top:12px"></div></div></div><div class="panel" style="margin-top:16px"><h2>售出商品清單</h2><div id="sellerSoldTable"></div></div>`);loadSellerDashboard();loadSellerProducts('listed')}
async function loadSellerDashboard(){const d=await api('seller_stats');document.querySelector('#sellerStats').innerHTML=`<div class="statgrid"><div class="stat"><span>已上架</span><strong>${countStatus(d.status_counts,'listed')}</strong></div><div class="stat"><span>已下架</span><strong>${countStatus(d.status_counts,'removed')+countStatus(d.status_counts,'pausing')}</strong></div><div class="stat"><span>已售出</span><strong>${countStatus(d.status_counts,'sold')}</strong></div><div class="stat"><span>總銷售額</span><strong>${money(d.sales?.revenue||0)}</strong></div></div><div class="split"><div class="panel"><h3>本月銷售</h3><p class="price">${money(d.month_sales?.revenue||0)}</p><p class="muted">本月售出 ${d.month_sales?.sold_count||0} 件</p></div><div class="panel"><h3>近 6 個月銷售趨勢</h3>${barRows(d.monthly||[])}</div></div>`;document.querySelector('#sellerSoldTable').innerHTML=soldTable(d.sold_items||[])}
async function updateProductStatus(id,status){await api('update_product_status',{product_id:id,status});await loadSellerDashboard();loadSellerProducts(status)}
async function renderAdmin(){const d=await api('admin_dashboard');const total=d.sales_summary||{},month=d.month_summary||{},reports=d.reports||[];const pendingMap={};reports.filter(r=>r.status==='pending').forEach(r=>{const key=String(r.product_id);if(!pendingMap[key])pendingMap[key]={...r,reasons:[],report_count:0};pendingMap[key].report_count++;pendingMap[key].reasons.push(r)});const pending=Object.values(pendingMap),done=reports.filter(r=>r.status!=='pending');shell(`<div class="head"><div><h2>平台管理</h2><p class="muted">同一商品的多筆檢舉會合併成一列審核。</p></div><button class="secondary" onclick="resetModerationLocks()">解除所有停權與檢舉鎖定</button></div><div class="statgrid"><div class="stat"><span>總售出件數</span><strong>${total.sold_count||0}</strong></div><div class="stat"><span>總成交額</span><strong>${money(total.revenue||0)}</strong></div><div class="stat"><span>本月售出</span><strong>${month.sold_count||0}</strong></div><div class="stat"><span>本月成交額</span><strong>${money(month.revenue||0)}</strong></div></div><div class="split"><div class="panel"><h3>近 6 個月成交額</h3>${barRows(d.monthly_sales||[])}</div><div class="panel"><h3>待審檢舉</h3><div class="list">${pending.map(r=>`<div class="row"><div><strong>${esc(r.product_title)}</strong><br><span class="pill">${r.report_count} 筆檢舉</span><div class="list" style="margin-top:8px">${r.reasons.map(x=>`<div class="muted">檢舉內容：${esc(x.reason)}</div>`).join('')}</div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="secondary" onclick="openProduct(${r.product_id},true)">查看商品</button><button onclick="reviewReport(${r.id},true,${r.product_id})">下架</button><button class="secondary" onclick="reviewReport(${r.id},false,${r.product_id})">保留</button></div></div>`).join('')||'<p class="muted">尚無待審檢舉</p>'}</div>${done.length?`<details style="margin-top:14px"><summary class="muted">已完成審核 ${done.length} 筆</summary><div class="list" style="margin-top:12px">${done.map(r=>`<div class="row"><div><strong>${esc(r.product_title)}</strong><br><span class="muted">檢舉原因：${esc(r.reason)}</span><br><span class="muted">狀態：${statusLabel(r.status)}</span>${r.admin_comment?`<p class="muted" style="margin:6px 0 0">平台評語：${esc(r.admin_comment)}</p>`:''}</div><button class="secondary" onclick="openProduct(${r.product_id},true)">查看商品</button></div>`).join('')}</div></details>`:''}</div></div><div class="split" style="margin-top:16px"><div class="panel"><h3>分類申請</h3>${d.category_requests.map(r=>reqRow(r,'category')).join('')||'<p class="muted">尚無申請</p>'}</div><div class="panel"><h3>大學申請</h3>${d.school_requests.map(r=>reqRow(r,'school')).join('')||'<p class="muted">尚無申請</p>'}</div></div><div class="panel" style="margin-top:16px"><h3>售出商品統整</h3>${soldTable(d.sold_items||[],true)}</div><div class="panel" style="margin-top:16px"><h3>所有訂單</h3>${d.orders.map(o=>`<p>${esc(o.product_title)}｜${statusLabel(o.status)}</p>`).join('')||'<p class="muted">尚無訂單</p>'}</div>`)}
async function resetModerationLocks(){if(!confirm('確定要解除目前所有帳號停權與商品檢舉鎖定嗎？'))return;try{await api('reset_moderation_locks',{});alert('已解除所有停權與檢舉鎖定');renderAdmin()}catch(err){alert(err.message)}}
function avatarHtml(url,name,cls='avatar-mini'){return `<span class="${cls}">${url?`<img src="${esc(url)}" alt="">`:esc(initials(name))}</span>`}
function ratingText(avg,count,label){return `${label}評價：${avg?avg:'尚無'}${Number(count||0)>0?` / 5（${count}）`:''}`}
function userChip(id,name,avatar,role,avg,count,school=''){return `<div class="user-chip"><button onclick="event.stopPropagation();openPublicProfile(${id},'${role}')" title="查看公開資料">${avatarHtml(avatar,name)}</button><div><button onclick="event.stopPropagation();openPublicProfile(${id},'${role}')" title="查看公開資料"><strong>${esc(name)}</strong></button><div class="rating-line">${esc(school||'')} ${ratingText(avg,count,role==='seller'?'賣家':'買家')}</div></div></div>`}
function shell(content){app.innerHTML=`<header class="top"><div><div class="brand">校園二手交易平台</div><div class="muted">${esc(me.display_name)}｜${me.role==='admin'?'平台方':'學生帳號'}</div></div><nav class="nav">${me.role==='admin'?`<button class="${view==='admin'?'active':''}" onclick="view='admin';render()">平台管理</button><button class="${view==='rules'?'active':''}" onclick="view='rules';render()">網站規範</button>`:['market:買家功能','sell:賣家功能','messages:訊息','orders:訂單','rules:網站規範'].map(x=>{let [id,t]=x.split(':');return `<button class="${view===id?'active':''}" onclick="view='${id}';render()">${t}</button>`}).join('')}</nav><div class="top-actions"><button class="avatar" title="個人中心" onclick="view='profile';render()">${me.avatar_url?`<img src="${esc(me.avatar_url)}" alt="">`:esc(initials(me.display_name))}</button><button class="secondary" onclick="logout()">登出</button></div></header><main>${content}</main>`}
async function renderRules(){const d=await api('site_rules');const rules=esc(d.rules||'').replace(/\n/g,'<br>');shell(`<div class="head"><div><h2>網站規範</h2><p class="muted">請共同維護校園二手交易平台的安全與公平。</p></div></div>${me.role==='admin'?`<form class="panel grid" onsubmit="updateRules(event)"><h3>編輯網站規範</h3><textarea name="rules" style="min-height:300px">${esc(d.rules||'')}</textarea><button>儲存網站規範</button><p class="muted">最後更新：${esc(d.updated_at||'尚未更新')}</p></form>`:`<div class="panel"><div style="line-height:1.9">${rules}</div><p class="muted" style="margin-top:16px">最後更新：${esc(d.updated_at||'尚未更新')}</p></div>`}`)}
async function updateRules(e){e.preventDefault();const rules=new FormData(e.target).get('rules');try{await api('update_site_rules',{rules});alert('網站規範已更新');renderRules()}catch(err){alert(err.message)}}
function openRegister(){modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><h2>註冊</h2><button class="secondary" onclick="closeModal()">關閉</button></div><form class="grid" onsubmit="register(event)"><div class="two grid"><label>帳號<input name="username" required></label><label>密碼<input name="password" type="password" required></label></div><div class="two grid"><label>Email<input name="email" type="email" required></label><label>姓名<input name="name" required></label></div><label>頭像（可不選）<input name="avatar" type="file" accept="image/*"></label><label>學校<select name="school">${opts.schools.map(s=>`<option>${esc(s.name)}</option>`)}</select></label><label>自我介紹<textarea name="bio"></textarea></label><button>建立帳號</button></form></div>`}
async function register(e){e.preventDefault();const f=new FormData(e.target);try{me=(await api('register',{username:f.get('username'),password:f.get('password'),email:f.get('email'),name:f.get('name'),school:f.get('school'),bio:f.get('bio'),avatar_url:await imgToData(f.get('avatar'))})).user;closeModal();render()}catch(err){alert(err.message)}}
async function openPublicProfile(id,role){const d=await api(`public_profile&id=${id}&role=${role}`),p=d.profile;modal.classList.remove('hidden');modal.innerHTML=`<div><div class="head"><div class="user-chip">${avatarHtml(p.avatar_url,p.display_name,'avatar')}<div><h2>${esc(p.display_name)}</h2><p class="muted">${esc(p.school_name||'未設定學校')}</p></div></div><button class="secondary" onclick="closeModal()">關閉</button></div><div class="statgrid"><div class="stat"><span>${role==='seller'?'賣家評價':'買家評價'}</span><strong>${p.rating_avg||'尚無'}</strong></div><div class="stat"><span>評價數</span><strong>${p.rating_count||0}</strong></div></div><p>${esc(p.bio||'')}</p><h3>評價紀錄</h3><div class="list">${d.reviews.map(r=>`<div class="row"><div><strong>${r.score} / 5</strong><br>${esc(r.review_text||'')}</div><span class="muted">${esc(r.reviewer_name)}</span></div>`).join('')||'<p class="muted">尚無評價</p>'}</div></div>`}
async function loadProducts(){const q=document.querySelector('#q')?.value||'',s=document.querySelector('#school')?.value||'',c=document.querySelector('#cat')?.value||'',sort=document.querySelector('#sort')?.value||'new';const data=await api(`products&q=${encodeURIComponent(q)}&school_id=${s}&category_id=${c}&sort=${sort}`);document.querySelector('#products').innerHTML=data.products.map(p=>`<article class="card"><img src="${esc(p.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt=""><div class="body"><h3>${esc(p.title)}</h3><div class="price">${money(p.price)}</div><div><span class="pill">${esc(p.school_name)}</span> <span class="pill">${esc(p.category_name)}</span></div>${userChip(p.seller_id,p.seller_name,p.seller_avatar_url,'seller',p.seller_rating,p.seller_rating_count,p.seller_school_name)}<button onclick="openProduct(${p.id})">查看</button></div></article>`).join('')||'<p class="muted">沒有商品。</p>'}
async function openProduct(id,readOnly=false){const d=await api('product_detail&id='+id);const p=d.product;modal.classList.remove('hidden');const actions=!readOnly&&p.seller_id!=me.id&&p.status==='listed'?`<p><button onclick="sendMessageForm(${p.id},${p.seller_id})">私訊賣家</button> <button onclick="createOrder(${p.id})">提出面交訂單</button> ${Number(p.report_cleared||0)===1?"":`<button class="danger" onclick="reportForm(${p.id})">檢舉商品</button>`}</p>`:'';const commentArea=readOnly?'<hr><h3>公開留言</h3>':`<hr><form class="grid" onsubmit="comment(event,${p.id})"><label>公開留言<textarea name="text" required></textarea></label><button>留言</button></form>`;modal.innerHTML=`<div><div class="head"><h2>${esc(p.title)}</h2><button class="secondary" onclick="closeModal()">關閉</button></div><img class="card" style="width:100%;max-height:320px" src="${esc(p.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt=""><p class="price">${money(p.price)}</p><p>${esc(p.description)}</p><p class="muted">${esc(p.school_name)}｜${esc(p.category_name)}</p>${Number(p.report_cleared||0)===1?`<p class="pill" style="background:#eef8f1;color:#23624d">平台已審核：符合規定，無法再次檢舉</p>`:""}${p.status!=='listed'?`<p class="pill">目前狀態：${statusLabel(p.status)}</p>`:''}${userChip(p.seller_id,p.seller_name,p.seller_avatar_url,'seller',p.seller_rating,p.seller_rating_count,p.seller_school_name)}${actions}${readOnly?'<p class="muted">平台方檢視模式：此頁僅供查看商品內容，不能進行交易、修改、留言或檢舉。</p>':''}${commentArea}<div class="list">${d.comments.map(c=>`<div class="row"><div><strong>${esc(c.user_name)}</strong><br>${esc(c.comment_text)}</div></div>`).join('')}</div></div>`}
async function renderProfile(){const d=await api('profile');const p=d.profile;const orders=d.buyer_orders||[],reports=d.reports||[];shell(`<div class="head"><div><h2>個人中心</h2><p class="muted">修改註冊資料、頭像，並查看買家購買紀錄與檢舉結果。</p></div></div><div class="split"><form class="panel grid" onsubmit="updateProfile(event)"><h3>更改資料</h3><div class="user-chip">${avatarHtml(p.avatar_url,p.display_name,'avatar')}<span class="muted">目前頭像</span></div><label>更換頭像（可不選）<input name="avatar" type="file" accept="image/*"></label><label>姓名<input name="display_name" value="${esc(p.display_name)}" required></label><label>Email<input name="email" type="email" value="${esc(p.email)}" required></label><label>學校<select name="school_id">${opts.schools.map(s=>`<option value="${s.id}" ${String(p.school_id)===String(s.id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>自我介紹<textarea name="bio">${esc(p.bio||'')}</textarea></label><button>儲存資料</button></form><div class="panel"><h3>帳號資訊</h3><p>帳號：${esc(p.username)}</p><p>Email：${esc(p.email)}</p><p>學校：${esc(p.school_name||'未設定')}</p><p>身份：${p.role==='admin'?'平台方':'學生帳號'}</p><button class="secondary" onclick="openPublicProfile(${p.id},'buyer')">查看我的買家公開頁</button> <button class="secondary" onclick="openPublicProfile(${p.id},'seller')">查看我的賣家公開頁</button></div></div><div class="panel" style="margin-top:16px"><h3>買家購買紀錄</h3><table class="table"><thead><tr><th>建立時間</th><th>商品</th><th>金額</th><th>賣家</th><th>學校</th><th>分類</th><th>狀態</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.created_at||'')}</td><td>${esc(o.product_title)}</td><td>${money(o.price)}</td><td>${esc(o.seller_name)}</td><td>${esc(o.school_name)}</td><td>${esc(o.category_name)}</td><td>${statusLabel(o.status)}</td></tr>`).join('')||'<tr><td colspan="7" class="muted">目前沒有購買紀錄</td></tr>'}</tbody></table></div><div class="panel" style="margin-top:16px"><h3>我的檢舉結果</h3><table class="table"><thead><tr><th>檢舉時間</th><th>商品</th><th>檢舉原因</th><th>狀態</th><th>平台評語</th></tr></thead><tbody>${reports.map(r=>`<tr><td>${esc(r.created_at||'')}</td><td>${esc(r.product_title)}</td><td>${esc(r.reason||'')}</td><td>${statusLabel(r.status)}</td><td>${esc(r.admin_comment||'尚未審核')}</td></tr>`).join('')||'<tr><td colspan="5" class="muted">目前沒有檢舉紀錄</td></tr>'}</tbody></table></div>`)}
async function updateProfile(e){e.preventDefault();const f=new FormData(e.target);try{const nextAvatar=await imgToData(f.get('avatar'));me=(await api('update_profile',{display_name:f.get('display_name'),email:f.get('email'),school_id:f.get('school_id'),bio:f.get('bio'),avatar_url:nextAvatar||me.avatar_url||''})).user;alert('資料已更新');renderProfile()}catch(err){alert(err.message)}}
async function renderMessages(){const d=await api('messages');if(!activeThread&&d.threads[0])activeThread=d.threads[0].id;shell(`<div class="head"><div><h2>訊息中心</h2><p class="muted">依商品建立對話，買家和賣家可以在這裡持續溝通面交細節。</p></div></div><div class="chat"><div class="panel"><h3>對話列表</h3><div class="list">${d.threads.map(t=>{const otherIsBuyer=me.id==t.seller_id;const name=otherIsBuyer?t.buyer_name:t.seller_name;const avatar=otherIsBuyer?t.buyer_avatar_url:t.seller_avatar_url;const role=otherIsBuyer?'buyer':'seller';const avg=otherIsBuyer?t.buyer_rating:t.seller_rating;const count=otherIsBuyer?t.buyer_rating_count:t.seller_rating_count;return `<div class="thread-btn ${activeThread==t.id?'active':''}" onclick="activeThread=${t.id};renderMessages()"><strong>${esc(t.product_title)}</strong><br>${userChip(otherIsBuyer?t.buyer_id:t.seller_id,name,avatar,role,avg,count)}<span>${money(t.price)}</span></div>`}).join('')||'<p class="muted">尚無私訊，可從商品頁點選私訊賣家開始。</p>'}</div></div><div class="panel chat-panel">${activeThread?chatPane(d):'<p class="muted">請選擇左側對話。</p>'}</div></div>`)}
function chatPane(d){const ms=d.messages[activeThread]||[],t=d.threads.find(x=>x.id==activeThread);return `<div><h3>${esc(t.product_title)}</h3><div class="grid">${userChip(t.buyer_id,t.buyer_name,t.buyer_avatar_url,'buyer',t.buyer_rating,t.buyer_rating_count)}${userChip(t.seller_id,t.seller_name,t.seller_avatar_url,'seller',t.seller_rating,t.seller_rating_count)}</div></div><div class="message-list grid">${ms.map(m=>`<div class="bubble ${m.sender_id==me.id?'mine':''}"><div class="user-chip">${avatarHtml(m.sender_avatar_url,m.sender_name)}<strong>${m.sender_id==me.id?'我':esc(m.sender_name)}</strong></div>${esc(m.message_text)}<small>${esc(m.created_at||'')}</small></div>`).join('')||'<p class="muted">尚無訊息。</p>'}</div><form class="grid" onsubmit="replyMessage(event,${activeThread})"><label>輸入訊息<textarea name="text" required placeholder="輸入面交時間、地點或商品問題"></textarea></label><button>送出訊息</button></form>`}
function favoriteKey(){return `campus_favorites_${me?.id||'guest'}`}
function getFavorites(){try{return JSON.parse(localStorage.getItem(favoriteKey())||'[]')}catch(e){return []}}
function saveFavorites(items){localStorage.setItem(favoriteKey(),JSON.stringify(items))}
function isFavorite(id){return getFavorites().some(x=>String(x.id)===String(id))}
function minimalProduct(p){return {id:p.id,title:p.title,price:p.price,image_url:p.image_url||fallbackImage,category_name:p.category_name||'',school_name:p.school_name||'',seller_name:p.seller_name||''}}
function toggleFavorite(product,e){if(e){e.preventDefault();e.stopPropagation()}let items=getFavorites();const id=String(product.id);const exists=items.some(x=>String(x.id)===id);items=exists?items.filter(x=>String(x.id)!==id):[minimalProduct(product),...items];saveFavorites(items);if(view==='favorites')renderFavorites();else document.querySelectorAll(`[data-fav-id="${CSS.escape(id)}"]`).forEach(btn=>{btn.classList.toggle('saved',!exists);btn.textContent=!exists?'♥':'♡';btn.title=!exists?'取消收藏':'加入收藏'});}
function productCard(p){const saved=isFavorite(p.id),encoded=encodeURIComponent(JSON.stringify(minimalProduct(p)));return `<article class="card"><div class="product-image-wrap"><img src="${esc(p.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt="${esc(p.title)}"><button class="heart-btn ${saved?'saved':''}" data-fav-id="${esc(p.id)}" type="button" title="${saved?'取消收藏':'加入收藏'}" onclick="toggleFavorite(JSON.parse(decodeURIComponent('${encoded}')),event)">${saved?'♥':'♡'}</button></div><div class="body"><h3>${esc(p.title)}</h3><div class="price">${money(p.price)}</div><div><span class="pill">${esc(p.category_name||'未分類')}</span></div><button onclick="openProduct(${p.id})">查看商品</button></div></article>`}
function ruleItem(icon,no,title,body){return `<div class="rule-item"><div class="rule-icon">${icon}</div><div><strong>${no} ${title}</strong><p>${body}</p></div></div>`}
const ruleMarker='__RULE_CARDS_JSON__';
function iconForRule(rule,i){const text=`${rule.group||''}${rule.title||''}${rule.body||''}`;if(/禁|違法|危險|下架/.test(text))return '🚫';if(/面交|安全|校園/.test(text))return '🏫';if(/停權|一個月|3/.test(text))return '⏳';if(/檢舉|審核|透明/.test(text))return '🔎';if(/溝通|誠信|赴約|禮貌/.test(text))return '🤝';if(/商品|資訊|照片|價格|描述/.test(text))return '🏷️';return ['📌','🧾','✅'][i%3]}
function lineToRule(line,i){let text=String(line||'').trim().replace(/^\d+[.、]\s*/,'');if(!text)return null;const parts=text.split('｜').map(x=>x.trim()).filter(Boolean);let rule;if(parts.length>=3)rule={group:parts[0],title:parts[1],body:parts.slice(2).join('｜')};else if(parts.length===2)rule={group:'平台規範',title:parts[0],body:parts[1]};else rule={group:'平台規範',title:text.slice(0,18),body:text};rule.icon=iconForRule(rule,i);return rule}
function parseRuleConfig(raw){const text=String(raw||'').trim();if(text.startsWith(ruleMarker)){try{const cfg=JSON.parse(text.slice(ruleMarker.length));if(Array.isArray(cfg.rules))return {rules:cfg.rules.map((r,i)=>({...r,icon:r.icon||iconForRule(r,i)}))};if(Array.isArray(cfg.custom))return {rules:[...baseRuleItems(),...cfg.custom.map((r,i)=>({...r,group:r.group||'平台補充規範',icon:r.icon||iconForRule(r,i)}))]};}catch(e){return {rules:baseRuleItems()}}}if(text){const rules=text.split(/\n+/).map(lineToRule).filter(Boolean);if(rules.length)return {rules}}return {rules:baseRuleItems()}}
function serializeRuleConfig(rules){return ruleMarker+JSON.stringify({rules})}
function customRuleCard(custom){return custom.length?`<section class="rules-card"><h3>D. 平台補充規範</h3><div class="rule-list">${custom.map((r,i)=>ruleItem(esc(r.icon||'📌'),String(i+9),esc(r.title||'補充規範'),esc(r.body||''))).join('')}</div></section>`:''}
function rulesCards(custom=[]){return `<div class="rules-grid"><section class="rules-card"><h3>A. 賣家與商品守則</h3><div class="rule-list">${ruleItem('🏷️','1','誠實敘述','商品資訊、照片、價格與新舊程度需如實描述。')}${ruleItem('🚫','2','禁售商品','禁止刊登違法、危險、侵權、菸酒、藥品、仿冒品或不適合校園交易的商品。')}</div></section><section class="rules-card"><h3>B. 交易與溝通禮儀</h3><div class="rule-list">${ruleItem('🤝','3','誠信赴約','交易雙方應以禮貌、誠信方式溝通，約定時間地點請準時赴約。')}${ruleItem('🏫','4','安全面交','建議選擇校園內公開場所面交，交付前確認商品狀態與金額。')}${ruleItem('⚠️','5','禁止惡意行為','不得惡意棄單、騷擾、詐騙、冒用資料或從事非交易用途。')}</div></section><section class="rules-card"><h3>C. 檢舉與處分</h3><div class="rule-list">${ruleItem('🛒','6','強制下架','檢舉成立，商品強制下架並記錄原因，該商品不得再次上架。')}${ruleItem('⏳','7','帳號停權','同一帳號月內下架達 3 件以上，帳號將停權 1 個月。')}${ruleItem('🔎','8','透明審核','平台審核必須填寫審核評語，並提供給雙方查看。')}</div></section>${customRuleCard(custom)}</div>`}
function customRuleRow(rule={}){return `<div class="custom-rule-row"><label>圖示<input name="icon" value="${esc(rule.icon||'📌')}" maxlength="4"></label><label>分類<input name="group" value="${esc(rule.group||'平台規範')}" placeholder="例如：交易與溝通"></label><label>標題<input name="title" value="${esc(rule.title||'')}" placeholder="例如：禁止私下轉帳詐騙"></label><label>內容<textarea name="body" placeholder="輸入這條規範的說明">${esc(rule.body||'')}</textarea></label><button type="button" class="secondary" onclick="this.closest('.custom-rule-row').remove()">刪除</button></div>`}
function addCustomRuleRow(rule={}){document.querySelector('#customRuleRows')?.insertAdjacentHTML('beforeend',customRuleRow(rule))}
function rulesToText(rules){return (rules.length?rules:baseRuleItems()).map(r=>`${r.group||'平台規範'}｜${r.title||'補充規範'}｜${r.body||''}`).join('\n')}
async function saveRuleCards(e){e.preventDefault();const rules=String(new FormData(e.target).get('rules_text')||'').trim();if(!rules){alert('網站規範不能空白');return}try{await api('update_site_rules',{rules});alert('網站規範已更新');renderRules()}catch(err){alert(err.message)}}
function baseRuleItems(){return [
  {icon:'🏷️',group:'賣家與商品守則',title:'誠實敘述',body:'商品資訊、照片、價格與新舊程度需如實描述。'},
  {icon:'🚫',group:'賣家與商品守則',title:'禁售商品',body:'禁止刊登違法、危險、侵權、菸酒、藥品、仿冒品或不適合校園交易的商品。'},
  {icon:'🤝',group:'交易與溝通禮儀',title:'誠信赴約',body:'交易雙方應以禮貌、誠信方式溝通，約定時間地點請準時赴約。'},
  {icon:'🏫',group:'交易與溝通禮儀',title:'安全面交',body:'建議選擇校園內公開場所面交，交付前確認商品狀態與金額。'},
  {icon:'⚠️',group:'交易與溝通禮儀',title:'禁止惡意行為',body:'不得惡意棄單、騷擾、詐騙、冒用資料或從事非交易用途。'},
  {icon:'🛒',group:'檢舉與處分',title:'強制下架',body:'檢舉成立，商品強制下架並記錄原因，該商品不得再次上架。'},
  {icon:'⏳',group:'檢舉與處分',title:'帳號停權',body:'同一帳號月內下架達 3 件以上，帳號將停權 1 個月。'},
  {icon:'🔎',group:'檢舉與處分',title:'透明審核',body:'平台審核必須填寫審核評語，並提供給雙方查看。'}
]}
function renderRuleLine(rule,i){return `<article class="rules-list-item"><div class="rule-icon">${esc(rule.icon||'📌')}</div><div><strong>${i+1}. ${esc(rule.title||'補充規範')}</strong><p>${esc(rule.body||'')}</p><small>${esc(rule.group||'平台補充規範')}</small></div></article>`}
function rulesList(rules=[]){return (rules.length?rules:baseRuleItems()).map(renderRuleLine).join('')}
async function renderRules(){const d=await api('site_rules');const cfg=parseRuleConfig(d.rules);const rules=cfg.rules&&cfg.rules.length?cfg.rules:baseRuleItems();shell(`<div class="rules-page list-style"><div class="rules-illustrations"><span>🧾</span><span>✉️</span><span>🛡️</span><span>🔍</span><span>📌</span><span>📬</span><span>✅</span><span>📄</span></div><div class="rules-head"><h2>網站規範</h2><p>請共同維護校園二手交易平台的安全與公平。</p></div><div class="rules-list-board">${rulesList(rules)}<p class="rules-updated">最後更新：${esc(d.updated_at||'尚未更新')}</p></div>${me.role==='admin'?`<form class="panel grid rules-edit" onsubmit="saveRuleCards(event)"><h3>編輯網站規範</h3><p class="rules-admin-note">直接在下方文字框修改即可。每一行是一條規範，格式為：分類｜標題｜內容。刪掉一行就是刪除該規範，新增一行就是新增規範。</p><textarea name="rules_text" class="rules-text-editor">${esc(rulesToText(rules))}</textarea><button>儲存網站規範</button></form>`:''}</div>`)}
function marketCategoryIcon(name){
  const text=String(name||'');
  if(/學士|畢業|禮服/.test(text))return '🎓';
  if(/宿舍|寢具|床|枕|被|收納/.test(text))return '🛏️';
  if(/實驗|器材|試管|燒杯|化學/.test(text))return '🧪';
  if(/文具|筆|鉛筆|原子筆|尺|橡皮擦/.test(text))return '✏️';
  if(/書|教材|原文/.test(text))return '📚';
  if(/社團|球|運動/.test(text))return '⚽';
  if(/3C|電腦|手機|鍵盤|滑鼠/.test(text))return '💻';
  if(/生活|用品|家具|杯/.test(text))return '🌿';
  if(/學習|工具/.test(text))return '🧰';
  return '🎒';
}
function setMarketCategory(id){
  const cat=document.querySelector('#cat');
  if(cat)cat.value=id||'';
  document.querySelectorAll('.category-card').forEach(btn=>btn.classList.toggle('active',String(btn.dataset.cat||'')===String(id||'')));
  loadProducts();
}
function shell(content){
  app.innerHTML=`<header class="top"><div><div class="brand">校園二手交易平台</div><div class="muted">${esc(me.display_name)}｜${me.role==='admin'?'平台方':'學生帳號'}</div></div><nav class="nav">${me.role==='admin'?`<button class="${view==='admin'?'active':''}" onclick="view='admin';render()">平台管理</button><button class="${view==='rules'?'active':''}" onclick="view='rules';render()">網站規範</button>`:['market:首頁','market:分類','market:最新上架','sell:賣家中心','rules:網站規範'].map(x=>{let [id,t]=x.split(':');return `<button class="${view===id?'active':''}" onclick="view='${id}';render()">${t}</button>`}).join('')}</nav><div class="top-actions">${me.role==='admin'?'':`<button class="icon-btn" title="搜尋" onclick="view='market';render();setTimeout(()=>document.querySelector('#q')?.focus(),80)">⌕</button><button class="icon-btn" title="收藏" onclick="view='favorites';render()">♥</button><button class="icon-btn" title="訊息" onclick="view='messages';render()">▣</button><button class="icon-btn" title="訂單" onclick="view='orders';render()">◷</button>`}<button class="avatar" title="個人中心" onclick="view='profile';render()">${me.avatar_url?`<img src="${esc(me.avatar_url)}" alt="">`:esc(initials(me.display_name))}</button><button class="secondary" onclick="logout()">登出</button></div></header><main>${content}</main>`;
}
async function render(){if(!me)return renderLogin();await loadOptions();if(view==='rules')return renderRules();if(view==='profile')return renderProfile();if(me.role==='admin')return renderAdmin();if(view==='favorites')return renderFavorites();if(view==='sell')return renderSell();if(view==='messages')return renderMessages();if(view==='orders')return renderOrders();return renderMarket()}
function renderFavorites(){const items=getFavorites();shell(`<div class="market-shell"><div class="head"><div><h2>我的收藏</h2><p class="muted">點商品卡上的愛心可以加入或取消收藏。</p></div><button class="secondary" onclick="view='market';render()">繼續逛商品</button></div>${items.length?`<div class="products market-products">${items.map(productCard).join('')}</div>`:`<div class="favorite-empty"><h3>目前還沒有收藏商品</h3><p class="muted">回到首頁，看到喜歡的商品就點一下愛心。</p><button onclick="view='market';render()">去逛逛</button></div>`}</div>`)}
function orderRole(o){return Number(o.buyer_id)===Number(me.id)?'買家':'賣家'}
function orderOtherName(o){return Number(o.buyer_id)===Number(me.id)?o.seller_name:o.buyer_name}
function orderStatusClass(status){return ['in_progress','completed','cancelled'].includes(status)?status:''}
function orderCard(o){const isBuyer=Number(o.buyer_id)===Number(me.id),otherId=isBuyer?o.seller_id:o.buyer_id,canFinish=o.status==='in_progress',canRate=o.status==='completed';return `<article class="order-card"><img class="order-thumb" src="${esc(o.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt="${esc(o.product_title)}"><div><h3 class="order-title">${esc(o.product_title)}</h3><div class="order-meta"><span class="status-pill ${orderStatusClass(o.status)}">${statusLabel(o.status)}</span><span class="pill">${orderRole(o)}</span><span class="pill">${money(o.price)}</span><span class="pill">對象：${esc(orderOtherName(o)||'')}</span></div><p class="muted" style="margin:8px 0 0">建立時間：${esc(o.created_at||'尚無')}</p></div><div class="order-actions"><button class="secondary" onclick="sendMessageForm(${o.product_id},${otherId})">私訊對方</button>${canFinish?`<button onclick="completeOrder(${o.id})">完成訂單</button>`:''}${canRate?`<button class="secondary" onclick="rateForm(${o.id})">評價</button>`:''}</div></article>`}
async function renderOrders(){const d=await api('orders'),orders=d.orders||[],doing=orders.filter(o=>o.status==='in_progress'),done=orders.filter(o=>o.status==='completed'),other=orders.filter(o=>!['in_progress','completed'].includes(o.status));shell(`<div class="orders-page"><section class="order-hero"><div><h2>訂單中心</h2><p class="muted">查看買賣雙方的交易進度，完成交易後可以留下評價。</p></div><button onclick="view='market';render()">繼續逛商品</button></section><div class="order-stats"><div class="order-stat"><span>進行中</span><strong>${doing.length}</strong></div><div class="order-stat"><span>已完成</span><strong>${done.length}</strong></div><div class="order-stat"><span>全部訂單</span><strong>${orders.length}</strong></div></div>${orders.length?`<section class="order-section"><div class="section-title"><h2>進行中</h2><span class="muted">${doing.length} 筆</span></div><div class="order-grid">${doing.map(orderCard).join('')||'<div class="favorite-empty">目前沒有進行中的訂單。</div>'}</div></section><section class="order-section"><div class="section-title"><h2>已完成</h2><span class="muted">${done.length} 筆</span></div><div class="order-grid">${done.map(orderCard).join('')||'<div class="favorite-empty">目前沒有已完成訂單。</div>'}</div></section>${other.length?`<section class="order-section"><div class="section-title"><h2>其他狀態</h2><span class="muted">${other.length} 筆</span></div><div class="order-grid">${other.map(orderCard).join('')}</div></section>`:''}`:`<div class="favorite-empty"><h3>目前尚無訂單</h3><p class="muted">看到想買的商品，可以從商品頁提出面交訂單。</p><button onclick="view='market';render()">去找商品</button></div>`}</div>`)}
async function renderMarket(){
  const cats=opts.categories.slice(0,5);
  shell(`<div class="market-shell"><section class="market-hero"><div class="hero-copy"><h1>好物不閒置<br>讓校園資源再利用！</h1><p>安心交易・誠信互動・永續校園</p><div class="hero-tags"><span>二手書籍</span><span>生活用品</span><span>學習工具</span></div></div></section><section class="market-section"><div class="section-title"><h2>熱門分類</h2><button class="link-btn" onclick="setMarketCategory('')">查看全部 ></button></div><div class="category-grid">${cats.map(c=>`<button type="button" class="category-card" data-cat="${c.id}" onclick="setMarketCategory(${c.id})"><span class="category-icon">${marketCategoryIcon(c.name)}</span><strong>${esc(c.name)}</strong></button>`).join('')||'<p class="muted">尚無分類</p>'}</div><div class="market-tools"><input id="q" placeholder="搜尋想找的商品"><select id="school"><option value="">全部學校</option>${opts.schools.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`)}</select><select id="cat"><option value="">全部分類</option>${opts.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`)}</select><select id="sort"><option value="new">最新上架</option><option value="cheap">價格最低</option></select><button onclick="loadProducts()">搜尋</button><button class="secondary" onclick="requestForm('category')">推薦分類</button></div></section><section class="market-section"><div class="section-title"><h2>最新上架</h2><button class="link-btn" onclick="requestForm('school')">推薦大學 ></button></div><div id="products" class="products market-products"></div></section></div>`);
  loadProducts();
}
async function loadProducts(){
  const q=document.querySelector('#q')?.value||'',s=document.querySelector('#school')?.value||'',c=document.querySelector('#cat')?.value||'',sort=document.querySelector('#sort')?.value||'new';
  const data=await api(`products&q=${encodeURIComponent(q)}&school_id=${s}&category_id=${c}&sort=${sort}`);
  const target=document.querySelector('#products');
  if(!target)return;
  target.innerHTML=data.products.map(productCard).join('')||'<p class="muted">目前沒有符合條件的商品。</p>';
}
function simpleRulesText(raw){
  const text=String(raw||'').trim();
  if(!text)return '';
  if(text.startsWith(ruleMarker)){
    try{
      const cfg=JSON.parse(text.slice(ruleMarker.length));
      const list=Array.isArray(cfg.rules)?cfg.rules:[];
      if(list.length)return list.map((r,i)=>`${i+1}. ${r.title||'網站規範'}：${r.body||''}`).join('\n');
    }catch(e){}
  }
  const lines=text.split(/\n+/).map(x=>x.trim()).filter(Boolean);
  if(lines.length&&lines.every(line=>line.includes('｜'))){
    return lines.map((line,i)=>{
      const parts=line.split('｜').map(x=>x.trim());
      return `${i+1}. ${parts[1]||parts[0]||'網站規範'}：${parts.slice(2).join('｜')||parts[1]||parts[0]||''}`;
    }).join('\n');
  }
  return text;
}
