  setTimeout(updateTopNotifications,0);
}
function productListItem(p,i){return `<article class="order-card"><img class="order-thumb" src="${esc(p.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt="${esc(p.title)}"><div><h3 class="order-title">#${i+1} ${esc(p.title)}</h3><div class="order-meta"><span class="pill">${money(p.price)}</span><span class="pill">${esc(p.category_name||'未分類')}</span><span class="pill">${esc(p.school_name||'')}</span></div><p class="muted" style="margin:8px 0 0">上架時間：${esc(p.created_at||'')}</p></div><div class="order-actions"><button onclick="openProduct(${p.id})">查看商品</button></div></article>`}
async function showProducts(targetId,params={},mode='grid'){
  const query=new URLSearchParams(params).toString();
  const data=await api(`products${query?'&'+query:''}`);
  const target=document.querySelector(targetId);
  if(!target)return;
  target.innerHTML=mode==='list'?data.products.map(productListItem).join('')||'<div class="favorite-empty">目前沒有商品。</div>':data.products.map(productCard).join('')||'<p class="muted">目前沒有商品。</p>';
}
