function selectCategory(id){
  const cat=document.querySelector('#cat');
  if(cat)cat.value=id||'';
  const found=opts.categories.find(c=>String(c.id)===String(id));
  const title=document.querySelector('#categoryTitle');
  if(title)title.textContent=found?`${found.name} 商品`:'全部分類商品';
  document.querySelectorAll('.category-card').forEach(btn=>btn.classList.toggle('active',String(btn.dataset.cat||'')===String(id||'')));
  loadProducts();
}
