function orderFlowStatusLabel(s){return {listed:'已上架',removed:'已下架',sold:'已售出',reserved:'交易處理中',pending:'等待賣家同意',in_progress:'交易處理中',completed:'已完成',cancelled:'已取消',approved:'已通過',rejected:'未通過'}[s]||s}
function notificationSeenKey(){return `campus_seen_notifications_${me?.id||'guest'}`}
function getSeenNotifications(){try{return JSON.parse(localStorage.getItem(notificationSeenKey())||'[]')}catch(e){return []}}
function setSeenNotifications(ids){localStorage.setItem(notificationSeenKey(),JSON.stringify([...new Set(ids)]))}
function buildNotificationItems(d){
  const items=[];
  (d.messages||[]).slice(0,5).forEach(m=>items.push({id:`msg-${m.id||m.created_at}`,t:'新訊息',b:`商品「${m.product_title}」有一則新私訊：${m.message_text}`,a:'點開訊息中心回覆對方',time:m.created_at||'',go:'messages'}));
  (d.orders||[]).forEach(o=>{
    const isBuyer=Number(o.buyer_id)===Number(me.id),isSeller=Number(o.seller_id)===Number(me.id);
    if(o.status==='pending'&&isSeller)items.push({id:`order-pending-${o.id}-${o.updated_at||o.created_at}`,t:'購買意願',b:`${o.buyer_name} 想購買「${o.product_title}」，目前正在等待你同意。`,a:'到訂單中心同意或先私訊確認',time:o.updated_at||o.created_at||'',go:'orders'});
    if(o.status==='in_progress'){
      if(isBuyer&&o.seller_completed_at&&!o.buyer_completed_at)items.push({id:`order-seller-done-${o.id}-${o.seller_completed_at}`,t:'對方已完成',b:`賣家已確認「${o.product_title}」完成，正在等你確認。`,a:'確認收到商品後按完成訂單',time:o.seller_completed_at,go:'orders'});
      else if(isSeller&&o.buyer_completed_at&&!o.seller_completed_at)items.push({id:`order-buyer-done-${o.id}-${o.buyer_completed_at}`,t:'對方已完成',b:`買家已確認「${o.product_title}」完成，正在等你確認。`,a:'確認交易完成後按完成訂單',time:o.buyer_completed_at,go:'orders'});
      else if(isBuyer&&!o.buyer_completed_at)items.push({id:`order-doing-buyer-${o.id}-${o.accepted_at||o.updated_at}`,t:'交易處理中',b:`「${o.product_title}」已由賣家同意，交易正在處理中。`,a:'面交完成後到訂單中心按完成訂單',time:o.accepted_at||o.updated_at||'',go:'orders'});
      else if(isSeller&&!o.seller_completed_at)items.push({id:`order-doing-seller-${o.id}-${o.accepted_at||o.updated_at}`,t:'交易處理中',b:`你已同意「${o.product_title}」這筆訂單，商品已暫時下架。`,a:'面交完成後到訂單中心按完成訂單',time:o.accepted_at||o.updated_at||'',go:'orders'});
    }
    if(o.status==='cancelled'&&isBuyer)items.push({id:`order-cancelled-${o.id}-${o.updated_at||o.created_at}`,t:'訂單已取消',b:`賣家已取消「${o.product_title}」這筆訂單。`,a:'可到訂單中心查看紀錄或重新找商品',time:o.updated_at||o.created_at||'',go:'orders'});
  });
  (d.ratings||[]).forEach(r=>items.push({id:`rating-${r.id}`,t:'待評價',b:`「${r.product_title}」已完成，還沒有留下評價。`,a:'到訂單中心幫這次交易評分',time:'',go:'orders'}));
  return items;
}
async function updateTopNotifications(){
  const badge=document.querySelector('#noticeBadge');
  if(!badge||!me||me.role==='admin')return;
  try{
    const d=await api('notifications'),items=buildNotificationItems(d),seen=getSeenNotifications(),unread=items.filter(x=>!seen.includes(x.id)).length;
    window.currentNotifications=items;
    badge.textContent=unread>99?'99+':String(unread);
    badge.classList.toggle('hidden',unread===0);
  }catch(e){}
}
async function toggleNotifications(){
  const menu=document.querySelector('#noticeMenu');
  if(!menu)return;
  const open=menu.classList.contains('hidden');
  if(!open){menu.classList.add('hidden');return}
  try{
    const d=await api('notifications'),items=buildNotificationItems(d),seen=getSeenNotifications();
    window.currentNotifications=items;
    menu.innerHTML=`<h3>提醒</h3>${items.length?items.slice(0,10).map(x=>`<button class="notice-item" onclick="openNotification('${x.go}')"><span><strong>${esc(x.t)}</strong><span class="notice-preview">${esc(x.b)}</span><span class="notice-action">${esc(x.a||'查看詳情')}</span>${x.time?`<span class="notice-time">${esc(x.time)}</span>`:''}</span>${seen.includes(x.id)?'':'<span class="notice-dot"></span>'}</button>`).join(''):'<p class="notice-empty">目前沒有新的提醒。</p>'}`;
    setSeenNotifications([...seen,...items.map(x=>x.id)]);
    document.querySelector('#noticeBadge')?.classList.add('hidden');
    menu.classList.remove('hidden');
  }catch(e){menu.innerHTML='<p class="notice-empty">提醒載入失敗。</p>';menu.classList.remove('hidden')}
}
function openNotification(nextView){document.querySelector('#noticeMenu')?.classList.add('hidden');view=nextView;render()}
async function renderHomeAlerts(){
