        if(isSeller&&!o.seller_completed_at)items.push({t:'待完成訂單',b:`「${o.product_title}」交易處理中，完成後請按完成訂單`,go:"view='orders';render()"});
        if(isBuyer&&o.seller_completed_at&&!o.buyer_completed_at)items.push({t:'對方已完成',b:`賣家已確認「${o.product_title}」完成，請確認是否完成`,go:"view='orders';render()"});
        if(isSeller&&o.buyer_completed_at&&!o.seller_completed_at)items.push({t:'對方已完成',b:`買家已確認「${o.product_title}」完成，請確認是否完成`,go:"view='orders';render()"});
      }
    });
    (d.ratings||[]).forEach(r=>items.push({t:'待評價',b:`「${r.product_title}」已完成，請留下評價`,go:"view='orders';render()"}));
    box.innerHTML=items.length?items.slice(0,6).map(x=>`<button class="row" onclick="${x.go}"><div><strong>${esc(x.t)}</strong><br><span class="muted">${esc(x.b)}</span></div><span class="pill">查看</span></button>`).join(''):'<p class="muted">目前沒有新的提醒。</p>';
  }catch(e){box.innerHTML='<p class="muted">提醒載入失敗。</p>'}
}
