function chatPane(d){const ms=d.messages[activeThread]||[],t=d.threads.find(x=>x.id==activeThread);return `<div><div class="head"><div><h3>${esc(t.product_title)}</h3><p class="muted">${money(t.price)}</p></div><div><button onclick="openProduct(${t.product_id})">查看商品 / 下訂</button></div></div><div class="grid">${userChip(t.buyer_id,t.buyer_name,t.buyer_avatar_url,'buyer',t.buyer_rating,t.buyer_rating_count)}${userChip(t.seller_id,t.seller_name,t.seller_avatar_url,'seller',t.seller_rating,t.seller_rating_count)}</div></div><div class="message-list grid">${ms.map(m=>`<div class="bubble ${m.sender_id==me.id?'mine':''}"><div class="user-chip">${avatarHtml(m.sender_avatar_url,m.sender_name)}<strong>${m.sender_id==me.id?'我':esc(m.sender_name)}</strong></div>${esc(m.message_text)}<small>${esc(m.created_at||'')}</small></div>`).join('')||'<p class="muted">尚無訊息。</p>'}</div><form class="grid" onsubmit="replyMessage(event,${activeThread})"><label>輸入訊息<textarea name="text" required placeholder="輸入面交時間、地點或商品問題"></textarea></label><button>送出訊息</button></form>`}
async function createOrder(id){try{const r=await api('create_order',{product_id:id});closeModal();alert(r.message||'已送出購買意願，等待賣家同意');view='orders';render()}catch(e){alert(e.message||'無法送出購買意願')}}
