async function completeOrder(id){try{const r=await api('complete_order',{order_id:id});alert(r.completed?'雙方已確認，訂單已完成':(r.waiting?'已通知對方確認完成訂單':'已送出完成確認'));renderOrders()}catch(e){alert(e.message||'無法完成訂單')}}
async function cancelOrder(id){if(!confirm('確定要取消這筆訂單嗎？取消後商品會恢復上架，買家會收到通知。'))return;try{const r=await api('cancel_order',{order_id:id});alert(r.message||'訂單已取消');renderOrders()}catch(e){alert(e.message||'無法取消訂單')}}
function orderCard(o){const isBuyer=Number(o.buyer_id)===Number(me.id),isSeller=Number(o.seller_id)===Number(me.id),otherId=isBuyer?o.seller_id:o.buyer_id,canAccept=isSeller&&o.status==='pending',canCancel=isSeller&&['pending','in_progress'].includes(o.status),canFinish=o.status==='in_progress'&&((isBuyer&&!o.buyer_completed_at)||(isSeller&&!o.seller_completed_at)),canRate=o.status==='completed';return `<article class="order-card"><img class="order-thumb" src="${esc(o.image_url||fallbackImage)}" onerror="this.onerror=null;this.src=fallbackImage" alt="${esc(o.product_title)}"><div><h3 class="order-title">${esc(o.product_title)}</h3><div class="order-meta"><span class="status-pill ${orderStatusClass(o.status)}">${orderFlowStatusLabel(o.status)}</span><span class="pill">${orderRole(o)}</span><span class="pill">${money(o.price)}</span><span class="pill">對象：${esc(orderOtherName(o)||'')}</span></div><p class="muted" style="margin:8px 0 0">${o.status==='pending'?'買家已提出購買意願，等待賣家同意。':o.status==='in_progress'?'雙方完成後都需要按完成訂單；賣家可視情況取消。':o.status==='cancelled'?'此訂單已取消，商品可重新交易。':'建立時間：'+esc(o.created_at||'尚無')}</p></div><div class="order-actions"><button class="secondary" onclick="sendMessageForm(${o.product_id},${otherId})">私訊對方</button><button class="secondary" onclick="openProduct(${o.product_id})">查看商品</button>${canAccept?`<button onclick="acceptOrder(${o.id})">同意訂單</button>`:''}${canFinish?`<button onclick="completeOrder(${o.id})">完成訂單</button>`:''}${canCancel?`<button class="danger" onclick="cancelOrder(${o.id})">取消訂單</button>`:''}${canRate?`<button class="secondary" onclick="rateForm(${o.id})">評價</button>`:''}</div></article>`}
async function renderOrders(){const d=await api('orders'),orders=d.orders||[];window.orderCache=orders;const pending=orders.filter(o=>o.status==='pending'),doing=orders.filter(o=>o.status==='in_progress'),done=orders.filter(o=>o.status==='completed'),other=orders.filter(o=>!['pending','in_progress','completed'].includes(o.status));shell(`<div class="orders-page"><section class="order-hero"><div><h2>訂單中心</h2><p class="muted">買家先提出購買意願，賣家同意後進入交易處理中，雙方都確認後才完成。</p></div><button onclick="view='categories';render()">繼續逛商品</button></section><div class="order-stats"><div class="order-stat"><span>待同意</span><strong>${pending.length}</strong></div><div class="order-stat"><span>處理中</span><strong>${doing.length}</strong></div><div class="order-stat"><span>已完成</span><strong>${done.length}</strong></div></div>${orders.length?`<section class="order-section"><div class="section-title"><h2>待賣家同意</h2><span class="muted">${pending.length} 筆</span></div><div class="order-grid">${pending.map(orderCard).join('')||'<div class="favorite-empty">目前沒有待同意訂單。</div>'}</div></section><section class="order-section"><div class="section-title"><h2>交易處理中</h2><span class="muted">${doing.length} 筆</span></div><div class="order-grid">${doing.map(orderCard).join('')||'<div class="favorite-empty">目前沒有交易處理中的訂單。</div>'}</div></section><section class="order-section"><div class="section-title"><h2>已完成</h2><span class="muted">${done.length} 筆</span></div><div class="order-grid">${done.map(orderCard).join('')||'<div class="favorite-empty">目前沒有已完成訂單。</div>'}</div></section>${other.length?`<section class="order-section"><div class="section-title"><h2>其他狀態</h2><span class="muted">${other.length} 筆</span></div><div class="order-grid">${other.map(orderCard).join('')}</div></section>`:''}`:`<div class="favorite-empty"><h3>目前尚無訂單</h3><p class="muted">看到想買的商品，可以從商品頁提出購買意願。</p><button onclick="view='categories';render()">去找商品</button></div>`}</div>`)}
async function render(){if(!me)return renderLogin();if(view==='market')view='home';await loadOptions();if(view==='rules')return renderRules();if(view==='profile')return renderProfile();if(me.role==='admin')return renderAdmin();if(view==='favorites')return renderFavorites();if(view==='sell')return renderSell();if(view==='messages')return renderMessages();if(view==='orders')return renderOrders();if(view==='categories')return renderCategories();if(view==='latest')return renderLatest();return renderHome()}
init();
</script>
</body>
</html>
